import {question,choices} from './math.mjs';
import {createChallenge,challengeDifficulty,recordAnswer,elapse,beginMemoryBoard,completeMemoryBoard} from './challenge-engine.mjs';

export function mountChallenge(app,{mode,settings,home,award,beep}) {
  const g=createChallenge(mode.id,settings.limit),$=s=>app.querySelector(s);
  let q,options=[],bad=[],cards=[],selected=[],matched=new Set(),locked=false,paused=false,disposed=false;
  let questionLeft=0,delay=null,delayLeft=0,clock=0,last=performance.now(),message='',kind='';
  const rules={practice:'12 câu, không đếm giờ. Sai: ngắt chuỗi và trừ 5 điểm. Bé vẫn được thử lại và xem gợi ý.',bubble:'Chạm đáp án trước khi hết giờ. Sai hoặc hết giờ: mất 1 mạng, ngắt chuỗi và trừ 5 điểm.',rocket:'Bay trong 60 giây. Sai hoặc quá giờ một câu: trừ thêm 3 giây, ngắt chuỗi và trừ 5 điểm.',mystery:'Tìm số còn thiếu trước khi hết giờ. Sai hoặc hết giờ: mất 1 mạng, ngắt chuỗi và trừ 5 điểm.',memory:'Ghép đúng: +20 điểm. Ghép sai không trừ điểm đã có. Ít lượt sai, thưởng cuối chặng càng cao. Không đếm giờ.'};
  app.innerHTML=`<div class="play-top"><button class="back" id="challenge-back">← Đảo trò chơi</button><span>${mode.icon} ${mode.title}</span><button class="back" id="challenge-pause">Tạm dừng</button></div><section class="play ${mode.color} challenge"><div class="challenge-hud" id="challenge-hud"></div><p class="challenge-rules">${rules[mode.id]}${mode.id==='memory'?'':' Điểm không âm.'}</p><div id="challenge-body"></div><div class="challenge-overlay" id="challenge-overlay" hidden></div></section>`;
  $('#challenge-back').onclick=home;$('#challenge-pause').onclick=togglePause;
  function difficulty(){return challengeDifficulty(g)}
  function hud(){const d=difficulty();$('#challenge-hud').innerHTML=`<div><span>Điểm</span><b>${g.score}</b></div><div><span>Cấp độ</span><b>${d.level}</b></div><div><span>${mode.id==='memory'?'Lượt ghép':'Chuỗi đúng'}</span><b>${mode.id==='memory'?g.attempts:g.streak}</b></div><div><span>${g.lives!==null?'Mạng':mode.id==='rocket'?'Thời gian':mode.id==='memory'?'Cặp đã ghép':'Đã đúng'}</span><b ${g.lives!==null?`aria-label="${g.lives} mạng"`:''}>${g.lives!==null?'♥'.repeat(g.lives)+'♡'.repeat(3-g.lives):mode.id==='rocket'?Math.ceil(g.remaining)+'s':g.correct}</b></div>`;const t=$('#question-clock');if(t)t.textContent=Math.ceil(questionLeft)+'s';const bar=$('#question-bar');if(bar)bar.style.width=Math.max(0,questionLeft/d.deadline*100)+'%'}
  function feedback(text,type=''){message=text;kind=type;const f=$('#feedback');if(f){f.textContent=text;f.className='challenge-feedback '+type}}
  function later(ms,fn){delay=fn;delayLeft=ms/1000}
  function newQuestion(){if(g.over||disposed)return;locked=false;bad=[];g.clean=true;message='Chọn đáp án của bé nhé!';kind='';const d=difficulty();q=question(d.limit,settings.op);options=choices(mode.id==='mystery'?q.b:q.answer,d.limit);questionLeft=d.deadline;renderQuestion()}
  function renderQuestion(){const d=difficulty(),mystery=mode.id==='mystery',bubble=mode.id==='bubble',rocket=mode.id==='rocket';
    $('#challenge-body').innerHTML=`<div class="play-label">${mode.id==='practice'?`CÂU ${g.correct+1} / 12`:`CẤP ${d.level}`} · PHẠM VI ${d.limit}</div><h2>${mystery?'Số nào đang trốn nhỉ?':bubble?'Chạm bong bóng đúng!':rocket?'Tiếp nhiên liệu cho tên lửa!':'Mình cùng tính nhé!'}</h2>${rocket?`<div class="challenge-rocket" aria-hidden="true">🚀 <span>${'✦ '.repeat(Math.min(d.level,8))}</span></div>`:''}<div class="equation">${q.a}<span>${q.sign}</span>${mystery?'<b class="unknown">?</b>':q.b}<span>=</span>${mystery?q.answer:'<b class="unknown">?</b>'}</div>${d.deadline?'<div class="challenge-time"><span>Thời gian câu này: <b id="question-clock"></b></span><div class="progress"><div id="question-bar"></div></div></div>':''}<div class="answers ${bubble?'bubbles':''}" style="--float-speed:${d.motion}s">${options.map((v,i)=>`<button data-answer="${v}" style="--i:${i}">${v}</button>`).join('')}</div><div id="feedback" role="status" aria-live="polite" class="challenge-feedback"></div>${mode.id==='practice'?'<button class="hint" id="hint">💡 Cho bé một gợi ý</button><div id="hint-content"></div>':''}<div id="challenge-next"></div>`;
    app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer),b));if($('#hint'))$('#hint').onclick=hint;feedback(message,kind);hud();
  }
  function hint(){if(locked||paused)return;g.clean=false;g.streak=0;hud();$('#hint').disabled=true;$('#hint-content').innerHTML=`<p>${q.sign==='+'?`Đếm ${q.a} chấm, thêm ${q.b} chấm.`:`Có ${q.a} chấm, bớt ${q.b} chấm bị gạch.`} Câu có gợi ý nhận 5 điểm.</p><div class="dots">${Array.from({length:q.sign==='+'?q.answer:q.a},(_,i)=>`<i class="${q.sign==='+'?(i>=q.a?'added':''):(i>=q.answer?'removed':'')}"></i>`).join('')||'<b>Không còn chấm nào: 0</b>'}</div>`}
  function freezeAnswers(){app.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);if($('#hint'))$('#hint').disabled=true}
  function answer(value,button){if(locked||paused||disposed||g.over||bad.includes(value))return;const expected=mode.id==='mystery'?q.b:q.answer;
    if(value!==expected){bad.push(value);recordAnswer(g,false);button.disabled=true;button.classList.add('wrong','challenge-shake');beep(false);feedback(g.lives!==null?'Chưa đúng. Mất 1 mạng — bé thử lại nhé!':mode.id==='rocket'?'Chưa đúng. −3 giây — bé thử lại nhé!':'Chưa đúng. Bé thử lại nhé!','miss');hud();if(g.over){locked=true;freezeAnswers();later(1000,finish)}return}
    locked=true;const points=recordAnswer(g,true);award();beep();button.classList.add('right','challenge-pop');freezeAnswers();feedback(`Chính xác! +${points} điểm${g.streak>1?` · Chuỗi ${g.streak}`:''}`,'success');hud();
    const go=()=>{if(mode.id==='practice'&&g.correct>=12)finish();else newQuestion()};
    if(mode.id==='practice'){$('#challenge-next').innerHTML='<button class="primary" id="next">Tiếp theo →</button>';$('#next').onclick=()=>{if(!paused)go()};$('#next').focus()}else later(Math.max(650,1100-difficulty().level*80),go);
  }
  function timeout(){if(locked||g.over)return;locked=true;recordAnswer(g,false);freezeAnswers();beep(false);feedback(`Hết giờ! ${q.a} ${q.sign} ${q.b} = ${q.answer}. ${g.lives!==null?'Mất 1 mạng.':'−3 giây.'}`,'miss');hud();later(1700,()=>g.over?finish():newQuestion())}
  function memoryBoard(){beginMemoryBoard(g);selected=[];matched=new Set();locked=false;g.clean=true;const d=difficulty();const unique=new Map();let tries=0;
    while(unique.size<d.pairs&&tries++<500){const x=question(d.limit,settings.op);if(!unique.has(x.answer))unique.set(x.answer,x)}
    // Guaranteed finite fallback for unusually repetitive random draws.
    for(let answer=0;unique.size<d.pairs;answer++)if(!unique.has(answer))unique.set(answer,{a:answer,b:0,sign:settings.op==='minus'?'−':'+',answer});
    cards=[...unique.values()].flatMap((x,i)=>[{pair:i,text:`${x.a} ${x.sign} ${x.b}`,kind:'q'},{pair:i,text:String(x.answer),kind:'a'}]);
    for(let i=cards.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}message='Lật hai thẻ để tìm một cặp.';kind='';renderMemory();
  }
  function renderMemory(){const d=difficulty();$('#challenge-body').innerHTML=`<div class="play-label">CHẶNG ${g.board} / 3 · ${matched.size} / ${d.pairs} CẶP</div><h2>Phép tính tìm bạn</h2><p class="instructions">Mở 2 thẻ = 1 lượt ghép. Thưởng chặng tối đa ${d.pairs*10} điểm; mỗi lượt sai giảm 5 điểm thưởng.</p><div class="memory-grid">${cards.map((c,i)=>{const visible=selected.includes(i)||matched.has(c.pair);return `<button class="memory-card ${visible?'flipped':''} ${matched.has(c.pair)?'matched':''}" data-card="${i}" aria-label="${visible?c.text:'Thẻ úp '+(i+1)}" ${matched.has(c.pair)||locked?'disabled':''}>${visible?c.text:'✦'}</button>`}).join('')}</div><div id="feedback" role="status" aria-live="polite" class="challenge-feedback"></div><div id="challenge-next"></div>`;app.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>flip(Number(b.dataset.card)));feedback(message,kind);hud()}
  function flip(i){if(paused||locked||disposed||g.over||selected.includes(i)||matched.has(cards[i].pair))return;if(selected.length===2){selected=[];message="Lật thêm một thẻ để tìm bạn nhé!";kind=""}selected.push(i);if(selected.length<2){renderMemory();return}const [a,b]=selected.map(j=>cards[j]),good=a.pair===b.pair&&a.kind!==b.kind;locked=good;g.clean=true;const points=recordAnswer(g,good);if(good){matched.add(a.pair);award();beep();message=`Thành đôi! +${points} điểm`;kind='success'}else{beep(false);message='Chưa thành đôi. Chạm thẻ khác để thử lượt mới nhé!';kind='miss'}if(!good){renderMemory();return}selected=[];locked=false;if(matched.size===difficulty().pairs){const bonus=completeMemoryBoard(g);hud();if(g.board===3)finish();else{locked=true;feedback(`Xong chặng ${g.board}! Thưởng +${bonus} điểm · ${g.boardAttempts} lượt ghép. Chặng sau có ${g.board===1?4:6} cặp thẻ.`,'success');$('#challenge-next').innerHTML='<button class="primary" id="next-board">Sang chặng tiếp →</button>';$('#next-board').onclick=()=>{if(!paused){g.board++;memoryBoard()}};$('#next-board').focus()}}else renderMemory()}
  function finish(){if(disposed)return;g.over=true;locked=true;delay=null;clearInterval(clock);$('#challenge-pause').disabled=true;const d=difficulty();$('#challenge-body').innerHTML=`<div class="finish-icon">${g.correct?'🏆':'🌱'}</div><h2>${g.lives===0?'Mình nghỉ một chút nhé!':'Hoàn thành chuyến phiêu lưu!'}</h2><p>${mode.id==='rocket'?'Hết giờ bay rồi! ':''}Mỗi lần thử, bé lại giỏi hơn một chút.</p><div class="results"><div><b>${g.score}</b><span>Điểm</span></div><div><b>${mode.id==='memory'?g.attempts:g.bestStreak}</b><span>${mode.id==='memory'?'Lượt ghép':'Chuỗi tốt nhất'}</span></div><div><b>${d.level}</b><span>Cấp đạt được</span></div></div>${mode.id==='memory'?`<p>Điểm ghép cặp: ${g.correct*20} · Thưởng các chặng: ${g.memoryBonus}</p>`:''}<p>⭐ ${g.correct} sao · ${g.attempts?Math.round(g.correct/g.attempts*100):0}% lượt đúng</p><div class="finish-actions"><button class="primary" id="challenge-again">↻ Chơi lại</button><button class="back" id="challenge-home">Chọn trò khác</button></div>`;$('#challenge-again').onclick=restart;$('#challenge-home').onclick=home;$('#challenge-again').focus();hud()}
  function restart(){Object.assign(g,createChallenge(mode.id,settings.limit));locked=false;paused=false;delay=null;message='';kind='';$('#challenge-pause').disabled=false;mode.id==='memory'?memoryBoard():newQuestion();last=performance.now();clock=setInterval(tick,100)}
  function togglePause(){if(g.over||disposed)return;paused=!paused;const overlay=$('#challenge-overlay');overlay.hidden=!paused;$('#challenge-body').inert=paused;$('#challenge-pause').textContent=paused?'Tiếp tục':'Tạm dừng';last=performance.now();if(paused){overlay.innerHTML='<h2>Mình nghỉ một chút nhé</h2><p>Trò chơi đã tạm dừng.</p><button class="primary" id="challenge-resume">Tiếp tục →</button>';$('#challenge-resume').onclick=togglePause;$('#challenge-resume').focus()}else $('#challenge-pause').focus()}
  function visibility(){if(document.hidden&&!paused&&!g.over)togglePause()}
  function key(e){if(e.key==='Escape'&&!e.repeat){e.preventDefault();togglePause()}}
  function tick(){const now=performance.now(),dt=Math.min(.25,(now-last)/1000);last=now;if(disposed||paused||document.hidden)return;if(g.over){if(delay){delayLeft-=dt;if(delayLeft<=0){const action=delay;delay=null;action()}}return}elapse(g,dt);if(g.over){finish();return}if(delay){delayLeft-=dt;if(delayLeft<=0){const action=delay;delay=null;action()}}else if(!locked&&questionLeft!==null&&mode.id!=='memory'){questionLeft=Math.max(0,questionLeft-dt);if(!questionLeft)timeout()}hud()}
  mode.id==='memory'?memoryBoard():newQuestion();clock=setInterval(tick,100);document.addEventListener('visibilitychange',visibility);document.addEventListener('keydown',key);
  return ()=>{disposed=true;clearInterval(clock);delay=null;document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',key)};
}
